function lrxNotifications(){const out=[];const pct=Number(state.settings?.priceIncreaseAlertPct||10);if(state.settings?.priceIncreaseAlertEnabled!==false){(state.purchasePriceHistory||[]).slice().reverse().forEach(h=>{if(Number(h.increasePct||0)>=pct)out.push({type:'PRECIO',title:'Aumento de costo',detail:`${h.product||'Producto'} · +${Number(h.increasePct||0).toFixed(1)}%`,date:h.date||h.createdAt})})}(state.permits||[]).forEach(r=>{if(r.expiryDate){const days=Math.ceil((new Date(r.expiryDate+'T23:59:59').getTime()-Date.now())/86400000);if(days<=30)out.push({type:'VENCIMIENTO',title:days<0?'Documento vencido':'Vencimiento próximo',detail:`${r.name||'Documento'} · ${days<0?'vencido':days+' días'}`,date:r.expiryDate})}});(state.nasRecords||[]).forEach(r=>{if(r.expiryDate){const days=Math.ceil((new Date(r.expiryDate+'T23:59:59').getTime()-Date.now())/86400000);const alertDays=Math.max(1,Number(r.alertDays||30));if(days<=alertDays)out.push({type:'VENCIMIENTO',title:days<0?'Documento NAS vencido':'Vencimiento NAS próximo',detail:`${r.name||'Documento'} · ${days<0?'vencido':days+' días'}`,date:r.expiryDate})}});(state.inventory||[]).forEach(i=>{const min=Number(i.minQty||0);if(min>0&&Number(i.qty||0)<=min)out.push({type:'INVENTARIO',title:'Stock bajo',detail:`${i.product||'Producto'} · ${Number(i.qty||0)} ${i.unit||''}`,date:now()})});return out.slice(0,40)}
let modalReturnFocus=null; let activeCameraStream=null;
function stopCameraStream(){if(activeCameraStream){try{activeCameraStream.getTracks().forEach(t=>t.stop())}catch(e){}activeCameraStream=null}}
function modal(html){const m=document.getElementById('modal'),b=document.getElementById('modalBox');if(!m||!b)return;close();modalReturnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;b.innerHTML=html;m.hidden=false;m.setAttribute('aria-hidden','false');m.classList.add('show');m.style.display='flex';m.style.pointerEvents='auto';m.style.zIndex='99999';document.body.classList.add('modal-open');requestAnimationFrame(()=>{const first=b.querySelector('input:not([type="hidden"]),select,textarea,button,[tabindex]:not([tabindex="-1"])');first?.focus({preventScroll:true})})}
function close(){try{stopCameraStream?.()}catch(e){console.warn('LRX camera cleanup',e)}const m=document.getElementById('modal'),b=document.getElementById('modalBox');if(m){m.classList.remove('show');m.style.display='none';m.style.pointerEvents='none';m.hidden=true;m.setAttribute('aria-hidden','true')}if(b)b.replaceChildren();document.body.classList.remove('modal-open');const target=modalReturnFocus;modalReturnFocus=null;if(target?.isConnected)requestAnimationFrame(()=>target.focus?.({preventScroll:true}))}
document.addEventListener('keydown',e=>{const m=document.getElementById('modal');if(!m||m.hidden)return;if(e.key==='Escape'){e.preventDefault();close();return}if(e.key==='Tab'){const fields=[...m.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(x=>x.offsetParent!==null);if(!fields.length){e.preventDefault();return}const first=fields[0],last=fields[fields.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function notificationModal(){const rows=lrxNotifications();modal(`<h3>Notificaciones LRX</h3><p class="muted">Alertas operativas pendientes.</p><div class="card">${rows.map(r=>`<div class="check-row" style="display:block;padding:10px 0;border-bottom:1px solid var(--line)"><b>${esc(r.title)}</b><br><small>${esc(r.detail)} · ${esc(r.date||'')}</small></div>`).join('')||'<div class="empty">No hay alertas pendientes.</div>'}</div><div class="actions"><button class="btn primary" data-action="close">Cerrar</button></div>`)}
function profileModal(){const u=currentUser();modal(`<h3>Perfil activo</h3><div class="card"><p><b>${esc(u.name||'Administrador LRX')}</b></p><p class="muted">Rol: ${esc(u.role||'Admin')}</p><p class="muted">ID: ${esc(u.id||'')}</p></div><div class="actions"><button class="btn" data-action="close">Cerrar</button><button class="btn primary" data-action="go-users">Usuarios y permisos</button></div>`)}

const SECURE_ROLES=['Admin','Socio','Accionista/Inversionista','Finanzas','Administración','Gerente General'];
function secureAccess(){return SECURE_ROLES.includes(currentUser().role)}
function requireSecure(){if(!secureAccess()){toast('Módulo restringido: solo socios/inversionistas y personal administrativo-financiero autorizado');return false}return true}
function exportValue(v){if(v===null||v===undefined)return '';if(v instanceof Date)return v.toISOString();if(typeof v==='object'){try{return JSON.stringify(v)}catch(e){return String(v)}}return String(v)}
function csvEscape(v){return JSON.stringify(exportValue(v))}
function exportRows(rows,name){if(!Array.isArray(rows)||!rows.length)return toast('No hay datos para exportar');const safe=rows.filter(r=>r&&typeof r==='object');if(!safe.length)return toast('No hay datos válidos para exportar');const headers=[...new Set(safe.flatMap(r=>Object.keys(r)))];const csv='\ufeff'+[headers.map(csvEscape).join(','),...safe.map(r=>headers.map(h=>csvEscape(r[h])).join(','))].join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${name}_${new Date().toISOString().slice(0,10)}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportRowsCSV(rows,name){return exportRows(rows,name)}
function exportExcel(rows,name){if(!rows.length)return toast('No hay datos para exportar');const headers=[...new Set(rows.flatMap(r=>Object.keys(r)))];const escX=v=>esc(exportValue(v));const html=`<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="UTF-8"><!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>LRX</x:Name><x:WorksheetOptions><x:DisplayGridlines/></x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]--></head><body><table border="1"><thead><tr>${headers.map(h=>`<th>${escX(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${headers.map(h=>`<td>${escX(r[h])}</td>`).join('')}</tr>`).join('')}</tbody></table></body></html>`;const blob=new Blob([html],{type:'application/vnd.ms-excel;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${name}_${new Date().toISOString().slice(0,10)}.xls`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function printHtml(title,body){
 const host=document.body, appShell=document.getElementById('app')||document.getElementById('root')||document.body;
 const previous=document.getElementById('lrxPrintOverlay'); if(previous) previous.remove();
 const overlay=document.createElement('div');overlay.id='lrxPrintOverlay';overlay.innerHTML=`<div class="lrx-print-page"><h1>LA REYNA MEXICAN FOOD XPRESS</h1><h2>${esc(title)}</h2>${body}<p class="small">Generado por Sistema de Gestión de Restaurante - LRX · ${fmt(now(),true)}</p></div>`;
 host.appendChild(overlay);
 const style=document.createElement('style');style.id='lrxPrintStyle';style.textContent=`#lrxPrintOverlay{position:fixed;inset:0;background:#fff;z-index:2147483647;overflow:auto;padding:28px;color:#172033;font-family:Arial,sans-serif}#lrxPrintOverlay h1{color:#244b93;border-bottom:3px solid #c92d6f;padding-bottom:10px}#lrxPrintOverlay table{width:100%;border-collapse:collapse}#lrxPrintOverlay th,#lrxPrintOverlay td{padding:8px;border:1px solid #ddd;text-align:left}#lrxPrintOverlay th{background:#f4f6fa}.lrx-print-page{max-width:1100px;margin:0 auto}.lrx-print-page .small{color:#667085;font-size:12px;margin-top:18px}@media print{body>*:not(#lrxPrintOverlay){display:none!important}#lrxPrintOverlay{position:static!important;overflow:visible!important;padding:0!important}#lrxPrintOverlay .lrx-print-page{max-width:none!important}}`;host.appendChild(style);
 let restored=false;const restore=()=>{if(restored)return;restored=true;overlay.remove();style.remove();window.removeEventListener('afterprint',restore);};window.addEventListener('afterprint',restore);
 setTimeout(()=>{window.print();setTimeout(restore,1200)},80);
}
function secureModule(title,subtitle,collection,fields,opts={}){if(!requireSecure())return head(title,subtitle)+`<div class=card><b>Acceso restringido.</b></div>`;const rows=state[collection]||[];const q=String(state[`_${collection}Q`]||'').toLowerCase();const filtered=rows.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q));const cols=fields.map(f=>f.key);const actions=`<button class="btn primary" data-action="secure-new" data-key="${collection}">＋ Nuevo</button> <button class="btn" data-action="secure-export" data-key="${collection}">Excel / CSV</button> <button class="btn" data-action="secure-print" data-key="${collection}">Imprimir / PDF</button>`;return head(title,subtitle,actions)+`<div class=card><div class=toolbar><input class="input search" id="secureSearch" data-key="${esc(collection)}" value="${esc(state[`_${collection}Q`]||'')}" placeholder="Buscar en ${esc(title)}..."></div><div class=tablewrap><table><thead><tr>${fields.map(f=>`<th>${esc(f.label)}</th>`).join('')}<th>Acciones</th></tr></thead><tbody>${filtered.slice().reverse().map(r=>`<tr>${cols.map(k=>`<td>${esc(r[k]??'—')}</td>`).join('')}<td><button class="btn" data-action="secure-edit" data-key="${collection}" data-id="${esc(r.id)}">Editar</button> <button class="btn danger" data-action="secure-delete" data-key="${collection}" data-id="${esc(r.id)}">Eliminar</button></td></tr>`).join('')||`<tr><td class=empty colspan=${fields.length+1}>No hay registros.</td></tr>`}</tbody></table></div></div>`}

function perms(){return ROLES[currentUser().role]||ROLE_SECURE[currentUser().role]||ROLES.Admin}
function permissionForAction(a){if(a.startsWith('export-')||a==='generic-export'||a==='inventory-export')return 'excel';if(a==='generic-print'||a==='print-label'||a==='print-event'||a==='print-checklist'||a==='pdf'||a==='png'||a==='jpg')return 'print';if(a.includes('delete')||a.startsWith('del-'))return 'delete';if(a.startsWith('new-')||a.startsWith('save-')||a.startsWith('add-')||a.startsWith('update-')||a.startsWith('quick-')||a.startsWith('start-')||a.startsWith('finish-')||a.startsWith('edit-')||a.endsWith('-edit')||['generic-add','create-label-format','create-label-type','edit-product','edit-note','edit-recipe','edit-bar','buy-shopping','inventory-adjust','inventory-count','save-adjust','save-physical-count','toggle-check','pin-note','switch-user','save-settings','digital-approve','digital-reject','digital-permissions','digital-set-master-pin'].includes(a))return 'create';return 'view'}
function canAction(a){if(['new-user','save-user','delete-user','switch-user'].includes(a)&&currentUser().role!=='Admin'){toast('Solo Admin puede administrar usuarios');return false}const need=permissionForAction(a);if(perms()[need]!==false)return true;toast('No tienes permiso para esta acción');return false}
function audit(event,detail=''){state.audit=Array.isArray(state.audit)?state.audit:[];state.audit.unshift({id:'AUD-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),date:new Date().toISOString(),userId:currentUser().id,user:currentUser().name,role:currentUser().role,event,action:lastAction,detail});state.audit=state.audit.slice(0,1000)}
function save(){const serialized=JSON.stringify(state);try{localStorage.setItem(KEY,serialized);try{localStorage.setItem(KEY+'.backup',JSON.stringify({savedAt:new Date().toISOString(),state}))}catch(backupError){console.warn('LRX backup skipped; primary data saved',backupError)}try{window.LRXCloudSync?.onLocalSave(state)}catch(syncError){console.warn('LRX cloud sync deferred; local save succeeded',syncError)}return true}catch(saveError){console.error('LRX persistence failed; existing data and backup were preserved',saveError);try{const persisted=localStorage.getItem(KEY);if(persisted)restoreStateSnapshot(persisted)}catch(restoreError){console.warn('LRX could not restore persisted state after save failure',restoreError)}toast('No se guardó: falta espacio local. Conservé los datos guardados y su respaldo; exporta una copia y libera espacio antes de volver a guardar.');return false}}
function nextCode(prefix,collection,minimum=1){const rows=Array.isArray(state[collection])?state[collection]:[];const re=new RegExp('^'+prefix+'-(\\d+)$','i');let max=0;rows.forEach(x=>{const m=String(x?.id||'').match(re);if(m)max=Math.max(max,Number(m[1])||0)});return prefix+'-'+String(Math.max(max+1,minimum)).padStart(3,'0')}
function nextCatalogCode(){const used=[...(master.products||[]),...(state.products||[])].map(x=>String(x?.id||'')).filter(x=>/^SUP-\d+$/i.test(x));let max=0;used.forEach(x=>max=Math.max(max,Number(x.split('-')[1])||0));return 'SUP-'+String(max+1).padStart(3,'0')}
function nextSupplierCode(){const used=[...(master.suppliers||[]),...(state.suppliers||[])].map(x=>String(x?.id||'')).filter(x=>/^SUPP-\d+$/i.test(x));let max=0;used.forEach(x=>max=Math.max(max,Number(x.split('-')[1])||0));return 'SUPP-'+String(max+1).padStart(3,'0')}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))} function money(v){return Number(v||0).toLocaleString('en-US',{style:'currency',currency:'USD'})} function fmt(v,withTime=false){if(!v)return'—';const value=String(v),date=/^\d{4}-\d{2}-\d{2}$/.test(value)?new Date(value+'T12:00:00'):new Date(v);return date.toLocaleString('es-US',withTime?{dateStyle:'short',timeStyle:'short'}:{dateStyle:'short'})} function now(){return new Date().toISOString()}
function toast(t){const x=document.getElementById('toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
function navGroupIcon(g){const map={'ADMINISTRACIÓN Y DIRECCIÓN':'inteligencia','RECURSOS HUMANOS':'empleados','CATÁLOGOS Y DATOS MAESTROS':'productos','COMPRAS Y ABASTECIMIENTO':'compras','INVENTARIO':'inventario','PRODUCCIÓN Y COCINA':'produccion','VENTAS Y POS':'ventas','DOCUMENTOS Y CUMPLIMIENTO':'documentos','OPERACIÓN':'checklists','REPORTES Y CONTROL':'reportes','HERRAMIENTAS':'calculadora','CONFIGURACIÓN Y CONTROL':'configuracion'};return icon(map[g]||'dashboard')}
function renderNav(){
 const n=document.getElementById('nav');
 if(!n)return;
 const visible=MODULES.filter(m=>perms().view);
 const groups=[]; let currentGroup=null;
 visible.forEach(m=>{if(m[0]==='dashboard'){groups.push({name:'',items:[m]});currentGroup=null;return} const g=group(m[0]); if(!currentGroup||currentGroup.name!==g){currentGroup={name:g,items:[]};groups.push(currentGroup)} currentGroup.items.push(m)});
 let saved='';try{saved=localStorage.getItem('lrx_nav_group_v1')||''}catch(e){}
 const activeGroup=group(current); const openGroup=activeGroup||saved;
 n.innerHTML=groups.map(g=>{
   if(!g.name)return `<button type="button" data-page="dashboard" class="${current==='dashboard'?'active':''}" aria-current="${current==='dashboard'?'page':'false'}"><span class="nav-icon" aria-hidden="true">${icon('dashboard')}</span><span class="nav-label">Dashboard</span></button>`;
   const isOpen=g.name===openGroup;
   return `<details class="nav-section" data-nav-group="${esc(g.name)}" ${isOpen?'open':''}><summary><span class="nav-section-icon" aria-hidden="true">${navGroupIcon(g.name)}</span><span class="nav-section-label">${esc(g.name)}</span><span class="nav-section-chevron" aria-hidden="true">›</span></summary><div class="nav-children">${g.items.map(m=>`<button type="button" data-page="${m[0]}" class="${m[0]===current?'active':''}" aria-current="${m[0]===current?'page':'false'}"><span class="nav-icon" aria-hidden="true">${icon(m[0])}</span><span class="nav-label">${esc(m[1])}</span></button>`).join('')}</div></details>`;
 }).join('');
 n.querySelectorAll('details.nav-section').forEach(d=>{d.addEventListener('toggle',()=>{if(!d.open)return;const name=d.dataset.navGroup||'';try{localStorage.setItem('lrx_nav_group_v1',name)}catch(e){}n.querySelectorAll('details.nav-section').forEach(other=>{if(other!==d)other.open=false})})});
}
function group(id){
 if(id==='dashboard')return'';
 if(['inteligencia','dre','sup','gerente','inversion','creditos','finanzas'].includes(id))return'ADMINISTRACIÓN Y DIRECCIÓN';
 if(['empleados'].includes(id))return'RECURSOS HUMANOS';
 if(['productos','ingredientes','categorias','proveedores','proveedores-comparacion'].includes(id))return'CATÁLOGOS Y DATOS MAESTROS';
 if(['compras','lista-compras'].includes(id))return'COMPRAS Y ABASTECIMIENTO';
 if(['inventario','movimientos','merma'].includes(id))return'INVENTARIO';
 if(['recetas','preelaborados','produccion','cocina','bar','foodcost','menu'].includes(id))return'PRODUCCIÓN Y COCINA';
 if(['ventas','rentabilidad','promociones','eventos'].includes(id))return'VENTAS Y POS';
 if(['activos-digitales','documentos','documentos-permisos','nas'].includes(id))return'DOCUMENTOS Y CUMPLIMIENTO';
 if(['reportes','auditoria'].includes(id))return'REPORTES Y CONTROL';
 if(['checklists','dieta','recursos'].includes(id))return'OPERACIÓN';
 if(['reportes'].includes(id))return'REPORTES Y CONTROL';
 if(['calculadora','convertidor','notas'].includes(id))return'HERRAMIENTAS';
 if(['configuracion'].includes(id))return'CONFIGURACIÓN Y CONTROL';
 return'OTROS';
}
