 const monthKey=d=>String(d||'').slice(0,7),monthStart=monthKey(from),monthEnd=monthKey(to),monthCount=Math.max(1,(Number(monthEnd.slice(0,4))-Number(monthStart.slice(0,4)))*12+Number(monthEnd.slice(5,7))-Number(monthStart.slice(5,7))+1),expenseMonths=new Map(),fixedCostPattern=/electric|electricity|electricidad|fpl|power|utility|utilities|gas|water|agua|rent|renta|alquiler|lease|telephone|phone|telefono|teléfono|internet|comcast|insurance|seguro|license|licencia|property tax|impuesto/i;
