function catalogSource(){
 const isSup=current==='sup';
 const userProducts=Array.isArray(state.products)?state.products.filter(p=>p?.active!==false):[];
 const source=isSup?effectiveMaster('products'):[...effectiveMaster('products'),...userProducts];
 const seen=new Set();
 return source.filter(p=>{const key=String(p.id||p.sku||p.name||'').toLowerCase();if(seen.has(key))return false;seen.add(key);return true});
}
const LRXPagination={
 normalize(page,pages){const p=Math.max(1,Number(pages)||1);return Math.min(Math.max(0,Number(page)||0),p-1)},
 pages(current,total){const last=Math.max(1,Number(total)||1),cur=Math.min(Math.max(0,Number(current)||0),last-1),out=[];const push=i=>{if(!out.includes(i))out.push(i)};push(0);if(cur>3)out.push('…');for(let i=Math.max(1,cur-2);i<=Math.min(last-2,cur+2);i++)push(i);if(cur<last-4)out.push('…');if(last>1)push(last-1);return out},
 markup(action,page,pages,total,start,end,extra=''){
  const safePages=Math.max(1,Number(pages)||1),safePage=this.normalize(page,safePages),nums=this.pages(safePage,safePages).map(x=>x==='…'?`<span class="pager-ellipsis" aria-hidden="true">…</span>`:`<button class="btn ${x===safePage?'primary':''}" data-action="${action}" data-page="${x}" ${extra} ${x===safePage?'aria-current="page"':''}>${x+1}</button>`).join('');
  return `<div class="pager-info">${total?`Mostrando ${start}–${end} de ${total}`:'0 registros'} · Página ${safePage+1} de ${safePages}</div><div class="pager-actions"><button class="btn" data-action="${action}" data-page="0" ${extra} ${safePage===0?'disabled':''}>Primera</button><button class="btn" data-action="${action}" data-page="${Math.max(0,safePage-1)}" ${extra} ${safePage===0?'disabled':''}>Anterior</button>${nums}<button class="btn" data-action="${action}" data-page="${Math.min(safePages-1,safePage+1)}" ${extra} ${safePage===safePages-1?'disabled':''}>Siguiente</button><button class="btn" data-action="${action}" data-page="${safePages-1}" ${extra} ${safePage===safePages-1?'disabled':''}>Última</button></div>`;
 }
};
function pagerMarkup(action,page,pages,total,start,end,extra=''){return LRXPagination.markup(action,page,pages,total,start,end,extra)}

