 const q=String(state[`_${type}RecipeQ`]||'').toLowerCase().trim();const filtered=all.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q));const size=Number(state[`_${type}RecipeSize`]||25);const pages=Math.max(1,Math.ceil(filtered.length/size));state[`_${type}RecipePage`]=Math.min(Math.max(0,Number(state[`_${type}RecipePage`]||0)),pages-1);const page=state[`_${type}RecipePage`];const visible=filtered.slice(page*size,(page+1)*size);
