 const stepList=document.getElementById('recipeProcessSteps');const paintRecipeSteps=()=>{if(stepList)stepList.innerHTML=recipeProcessStepMarkup(window._lrxRecipeProcessItems||[])};document.getElementById('recipeAddStep')?.addEventListener('click',()=>{const items=window._lrxRecipeProcessItems||[];if(items.length>=12)return toast('Se permiten hasta 12 pasos por ficha.');items.push({caption:'',name:'',dataUrl:'',file:null});window._lrxRecipeProcessItems=items;paintRecipeSteps()});stepList?.addEventListener('input',e=>{const row=e.target.closest('.recipe-process-step');if(!row||!e.target.matches('.recipe-step-caption'))return;const item=window._lrxRecipeProcessItems?.[Number(row.dataset.stepIndex)];if(item)item.caption=e.target.value});stepList?.addEventListener('click',e=>{const row=e.target.closest('.recipe-process-step');if(e.target.closest('.recipe-step-photo'))row?.querySelector('.recipe-step-file')?.click();if(e.target.closest('.recipe-step-remove')&&row){window._lrxRecipeProcessItems.splice(Number(row.dataset.stepIndex),1);paintRecipeSteps()}});stepList?.addEventListener('change',e=>{if(!e.target.matches('.recipe-step-file'))return;const row=e.target.closest('.recipe-process-step'),i=Number(row?.dataset.stepIndex),file=e.target.files?.[0];if(!file)return;if(file.size>12*1024*1024){toast('La foto debe pesar menos de 12 MB.');e.target.value='';return}const item=window._lrxRecipeProcessItems?.[i];if(!item)return;item.file=file;item.name=file.name;item.previewUrl=URL.createObjectURL(file);const label=row.querySelector('.recipe-step-filename');if(label)label.textContent=file.name;let preview=row.querySelector('.recipe-step-preview');if(preview){preview.src=URL.createObjectURL(file)}else{row.insertAdjacentHTML('beforeend',`<img class="recipe-step-preview" alt="Foto del paso ${i+1}">`);preview=row.querySelector('.recipe-step-preview');preview.src=URL.createObjectURL(file)}e.target.value=''});
 const raf=document.getElementById('recipeAttachInput');
