 const processPhotoInput=document.getElementById('recipeProcessPhotoInput');document.getElementById('recipePhotoBtn')?.addEventListener('click',()=>processPhotoInput?.click());processPhotoInput?.addEventListener('change',()=>{const files=[...(processPhotoInput.files||[])];if(!files.length)return;const items=window._lrxRecipeProcessItems||[];for(const file of files){if(!file.type.startsWith('image/'))continue;if(file.size>12*1024*1024){toast(`${file.name}: cada foto debe pesar menos de 12 MB.`);continue}if(items.length>=12){toast('Límite de 12 pasos por ficha.');break}items.push({caption:'',name:file.name,file,dataUrl:'',previewUrl:URL.createObjectURL(file)})}window._lrxRecipeProcessItems=items;processPhotoInput.value='';const list=document.getElementById('recipeProcessSteps');if(list)list.innerHTML=recipeProcessStepMarkup(items);if(photoStatus)photoStatus.textContent=`${items.length} pasos; guarda la ficha para conservar las fotos.`});document.getElementById('recipeCameraBtn')?.addEventListener('click',()=>cameraCapture(file=>{const items=window._lrxRecipeProcessItems||[];if(items.length>=12)return toast('Límite de 12 pasos por ficha.');items.push({caption:'',name:file.name,file,dataUrl:'',previewUrl:URL.createObjectURL(file)});window._lrxRecipeProcessItems=items;const list=document.getElementById('recipeProcessSteps');if(list)list.innerHTML=recipeProcessStepMarkup(items);if(photoStatus)photoStatus.textContent=`${items.length} pasos; guarda la ficha para conservar las fotos.`}));
 document.getElementById('recipeOcrBtn')?.addEventListener('click',()=>recipeImportAction(type));
