 modal(`<h3>${r?'Editar':'Nuevo'} registro de Gerente</h3><div class="formgrid"><div class="field"><label>Fecha</label><input id="mgrDate" type="date" value="${esc(String(r?.date||now()).slice(0,10))}"></div><div class="field"><label>Turno</label><select id="mgrShift">${['Mañana','Tarde','Noche','Doble','Otro'].map(x=>`<option ${r?.shift===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Gerente / responsable</label><input id="mgrManager" value="${esc(r?.manager||currentUser()?.name||'')}" autocomplete="off"></div><div class="field"><label>Área</label><select id="mgrArea">${['General','Servicio','Cocina','Bar','Proveedor','Personal','Mantenimiento','Cliente','Seguridad','Otro'].map(x=>`<option ${r?.area===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Tipo</label><select id="mgrKind">${['Jornada','Incidente','Servicio','Cocina','Proveedor','Personal','Mantenimiento','Cliente','Seguridad','Otro'].map(x=>`<option ${r?.kind===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Cómo estuvo la jornada</label><select id="mgrWorkload">${['Ocupada','Media','Floja','Normal','Otro'].map(x=>`<option ${r?.workload===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Título</label><input id="mgrTitle" value="${esc(r?.title||'')}" placeholder="Resumen del turno o incidente"></div><div class="field full"><label>Personas involucradas / testigos</label><input id="mgrPeople" value="${esc(r?.people||'')}" autocomplete="off"></div><div class="field"><label>Estado</label><select id="mgrStatus">${['ABIERTO','EN SEGUIMIENTO','CERRADO'].map(x=>`<option ${String(r?.status||'ABIERTO')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Detalle, acciones tomadas y seguimiento</label><textarea id="mgrDescription" rows="5">${esc(r?.description||'')}</textarea></div><div class="field full"><label>Adjuntar fotos (se comprimen antes de guardarlas)</label><input id="mgrPhotos" type="file" accept="image/*" multiple><div class="muted">${(r?.photos||[]).map(p=>esc(p.name)).join(' · ')||'Sin fotos adjuntas.'}</div></div></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" id="managerSaveBtn">Guardar bitácora</button></div>`);
 document.getElementById('managerSaveBtn')?.addEventListener('click',()=>saveManagerLog(id));
