async function compressManagerPhoto(file){try{const bitmap=await createImageBitmap(file),scale=Math.min(1,1100/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();let q=.72,data=canvas.toDataURL('image/jpeg',q);while(data.length>220000&&q>.38){q-=.08;data=canvas.toDataURL('image/jpeg',q)}return data.length<=220000?data:null}catch(e){console.warn('Could not compress manager photo',e);return null}}
async function saveManagerLog(id=''){
 const g=x=>document.getElementById(x)?.value||'',title=g('mgrTitle').trim(),date=g('mgrDate')||now().slice(0,10);if(!title)return toast('Escribe un título para el registro');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date))||new Date(date+'T12:00:00').toISOString().slice(0,10)!==date)return toast('Indica una fecha válida');
 const r=id?(state.managerLogs||[]).find(x=>String(x.id)===String(id)):null;if(id&&!r)return toast('No se encontró el registro de bitácora');const selected=[...(document.getElementById('mgrPhotos')?.files||[])];if(selected.length>4)return toast('Adjunta hasta 4 fotos por registro');const files=selected.filter(f=>f.type.startsWith('image/'));if(files.length!==selected.length)return toast('Solo se admiten archivos de imagen');let photos=[];for(const file of files){const data=await compressManagerPhoto(file);if(data)photos.push({name:file.name,dataUrl:data})}if(files.length&&photos.length!==files.length)return toast('No se pudieron comprimir todas las fotos. Reduce su tamaño e inténtalo de nuevo; no se guardó el registro.');
 const obj={...(r||{}),id:r?.id||'MGR-'+Date.now(),date,shift:g('mgrShift'),manager:g('mgrManager').trim(),area:g('mgrArea'),kind:g('mgrKind'),workload:g('mgrWorkload'),title,people:g('mgrPeople').trim(),status:g('mgrStatus'),description:g('mgrDescription').trim(),photos:[...(r?.photos||[]),...photos],createdAt:r?.createdAt||now(),updatedAt:now()};
 const snapshot=JSON.stringify(state);state.managerLogs=Array.isArray(state.managerLogs)?state.managerLogs:[];state.managerLogs=r?state.managerLogs.map(x=>String(x.id)===String(id)?obj:x):[obj,...state.managerLogs];audit(r?'MANAGER_LOG_EDIT':'MANAGER_LOG_CREATE',String(obj.id)+' · '+obj.kind+' · '+obj.title);if(!save()){restoreStateSnapshot(snapshot);return}close();render();toast('Registro de bitácora guardado');
}
function deleteManagerLog(id){const row=(state.managerLogs||[]).find(x=>String(x.id)===String(id));if(!row)return toast('No se encontró el registro.');if(!confirm('¿Eliminar este registro de la bitácora?'))return;const snapshot=JSON.stringify(state);state.managerLogs=(state.managerLogs||[]).filter(x=>String(x.id)!==String(id));audit('MANAGER_LOG_DELETE',String(row.id)+' · '+String(row.title||row.kind||''));if(!save()){restoreStateSnapshot(snapshot);return}render();toast('Registro eliminado de la bitácora')}
function budgetModal(id=""){const r=id?(state.budgets||[]).find(x=>String(x.id)===String(id)):null;modal(`<h3>${r?"Editar":"Nuevo"} presupuesto</h3><div class="formgrid"><div class="field"><label>Periodo</label><input id="budPeriod" type="month" value="${esc(r?.period||new Date().toISOString().slice(0,7))}"></div><div class="field"><label>Categoría</label><input id="budCat" value="${esc(r?.category||"")}" placeholder="Renta, alimentos, nómina..."></div><div class="field"><label>Monto presupuestado</label><input id="budAmt" type="number" step=".01" value="${Number(r?.amount||0)}"></div></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="save-budget" data-id="${esc(id)}">Guardar</button></div>`)}
function promotions(){
 const rows=state.promotions||[];
 const calc=r=>{const normal=Number(r.normal||0),promo=Number(r.promo||0),qty=Math.max(1,Number(r.qty||1)),cost=Number(r.cost||0),comm=Math.max(0,Number(r.commission||0))/100,cardPct=Math.max(0,Number(r.cardFeePct||0))/100,cardFixed=Math.max(0,Number(r.cardFee||0)),fixedFee=Math.max(0,Number(r.fixedFee||0)),mkt=Math.max(0,Number(r.marketing||0));const gross=promo*qty,discount=Math.max(0,(normal-promo))*qty,commission=gross*comm,card=gross*cardPct+cardFixed,net=gross-commission-card-fixedFee,profit=net-cost*qty-mkt;return {normal,promo,qty,cost,comm,cardPct,cardFixed,fixedFee,mkt,gross,discount,commission,card,net,profit,margin:net?profit/net*100:0}};
 return head('Promociones / Marketing','Promociones, combos y descuentos con impacto económico real.',`<button class="btn primary" data-action="new-promotion">＋ Nueva promoción</button> <button class="btn" data-action="export-promotions">Exportar CSV</button> <button class="btn" data-action="promotions-print">Imprimir / PDF</button>`)+
 `<div class="grid"><div class="card kpi"><small>Promociones</small><strong>${rows.length}</strong></div><div class="card kpi"><small>Activas</small><strong>${rows.filter(r=>String(r.status).toUpperCase()==='ACTIVA').length}</strong></div><div class="card kpi"><small>Inversión marketing</small><strong>${money(rows.reduce((a,r)=>a+Number(r.marketing||0),0))}</strong></div></div>`+
 `<div class="card" style="margin-top:14px"><div class="tablewrap"><table><thead><tr><th>Promoción</th><th>Tipo</th><th>Precio normal</th><th>Precio promo</th><th>Desc.</th><th>Comisión</th><th>Costo</th><th>Utilidad</th><th>Margen</th><th>Estado</th><th></th></tr></thead><tbody>${rows.slice().reverse().map(r=>{const d=calc(r);return `<tr><td><b>${esc(r.name)}</b><small>${esc(r.product||r.products||'')}</small></td><td>${esc(r.type||'DESCUENTO')}</td><td>${money(d.normal)}</td><td>${money(d.promo)}</td><td>${d.normal?((1-d.promo/d.normal)*100).toFixed(1):'0.0'}%</td><td>${(d.comm*100).toFixed(1)}%</td><td>${money(d.cost*d.qty)}</td><td>${money(d.profit)}</td><td>${d.margin.toFixed(1)}%</td><td><span class="status">${esc(r.status||'PROGRAMADA')}</span></td><td><button class="btn" data-action="edit-promotion" data-id="${esc(r.id)}">Editar</button> <button class="btn danger" data-action="delete-promotion" data-id="${esc(r.id)}">Eliminar</button></td></tr>`}).join('')||'<tr><td colspan="11" class="empty">No hay promociones.</td></tr>'}</tbody></table></div></div>`;
}
