function parseStructuredInvoiceLines(text){
 const source=String(text||'').replace(/\r/g,'');
 if(!/(ITEM|PRODUCT|SKU|CODE|CÓDIGO)[\s\S]{0,180}(QTY|QUANTITY|CANTIDAD)[\s\S]{0,180}(DESCRIPTION|PRODUCT|DESCRIPCIÓN|ARTÍCULO)[\s\S]{0,180}(AMOUNT|EXTENDED|TOTAL|IMPORTE|COST)/i.test(source))return [];
 const products=[...(master?.products||[]),...(state?.products||[])],lines=[];
 const hasCategoryColumn=/\b(CAT|CATEGORY|CATEGOR[IÍ]A)\b/i.test(source.split('\n').find(x=>/(ITEM|PRODUCT|SKU|CODE|CÓDIGO)/i.test(x)&&/(QTY|QUANTITY|CANTIDAD)/i.test(x))||'');
 for(const raw of source.split('\n')){
  const line=raw.trim().replace(/\s+/g,' ');if(!line||/^(SUBTOTAL|INVOICE\s+TOTAL|TOTAL|TAX|BALANCE)\b/i.test(line))continue;
  const m=line.match(/^([A-Z0-9][A-Z0-9._/-]{3,})\s+(\d+(?:\.\d+)?)\s+(?:(CASE|CS|EA|EACH|LB|LBS|PK|CT|UNIT|UNITS|CAJA|UNIDAD(?:ES)?)\s+)?(.+?)\s+((?:\$?\d[\d,]*\.\d{2}\s*){1,4})$/i);
  if(!m)continue;
  const [,code,qtyText,unitText,rawDesc,priceText]=m,qty=Number(qtyText),prices=priceText.trim().split(/\s+/).map(x=>Number(x.replace(/[$,]/g,''))).filter(Number.isFinite),total=prices[prices.length-1];
  if(!(qty>0)||!(total>=0))continue;
  const name=(hasCategoryColumn?rawDesc.replace(/\s+\d{1,3}$/,''):rawDesc).trim().replace(/\s+/g,' '),product=products.find(p=>[p.code,p.sku,p.itemCode,p.upc,p.barcode].some(v=>String(v||'').trim().toLowerCase()===code.toLowerCase()));
  lines.push({product:product?.name||name,code,qty,unit:unitText||'unidad',unitCost:total/qty,total,lineTotal:total,invoiceDescription:name,unitPrice:prices.length>1?prices[0]:total/qty});
 }
 return lines;
}
function parseInvoiceToPurchase(text){
 const empty={supplier:'',invoice:'',date:'',subtotal:0,tax:0,total:0,lines:[]};
 const parsed=window.LRXPurchaseEngine?window.LRXPurchaseEngine.parseInvoice(text,window._lrxPurchaseLayout||[],purchaseEngineContext()):empty;
 if(!Array.isArray(parsed.lines)||!parsed.lines.length){const lines=parseStructuredInvoiceLines(text);if(lines.length)parsed.lines=lines;}
 return parsed;
}


function productRecordById(id){const all=[...(master.products||[]),...(state.products||[])];return all.find(x=>String(x.id)===String(id))||null}
function productModal(id=''){
 const p=id?productRecordById(id):null;
 modal(`<h3>${p?'Editar producto':'Nuevo producto'}</h3><p class="muted">Producto maestro para Inventario, SUP, Recetas y Food Cost.</p><div class="formgrid"><div class="field full"><label>Nombre</label><input id="prdName" value="${esc(p?.name||'')}"></div><div class="field"><label>Código / SKU</label><input id="prdCode" value="${esc(p?.code||p?.sku||'')}"></div><div class="field"><label>Barcode / UPC</label><input id="prdBarcode" value="${esc(p?.barcode||p?.upc||'')}"></div><div class="field"><label>Categoría</label><input id="prdCategory" value="${esc(p?.category||'')}"></div><div class="field"><label>Proveedor</label><input id="prdSupplier" list="prdSuppliers" value="${esc(p?.supplier||'')}"><datalist id="prdSuppliers">${[...(master.suppliers||[]),...(state.suppliers||[])].map(x=>`<option value="${esc(typeof x==='string'?x:x.name||'')}">`).join('')}</datalist></div><div class="field"><label>Presentación</label><input id="prdPurchaseUnit" value="${esc(p?.purchaseUnit||p?.unit||'unidad')}"></div><div class="field"><label>Costo presentación</label><input id="prdPackPrice" type="number" step="0.0001" value="${p?.packPrice??p?.purchasePrice??p?.price??''}"></div><div class="field"><label>Contenido</label><input id="prdPackQty" type="number" min="0.0001" step="0.0001" value="${p?.packQty??''}"></div><div class="field"><label>Unidad contenido</label><select id="prdPackUnit">${['lb','oz','kg','g','gal','qt','pt','L','mL','fl oz','unidad'].map(u=>`<option value="${u}" ${(p?.packUnit||p?.standardUnit||p?.unit||'unidad')===u?'selected':''}>${u}</option>`).join('')}</select></div><div class="field"><label>Unidad estándar</label><select id="prdStandardUnit">${['lb','oz','kg','g','gal','qt','pt','L','mL','fl oz','unidad'].map(u=>`<option value="${u}" ${(p?.standardUnit||p?.unit||'unidad')===u?'selected':''}>${u}</option>`).join('')}</select></div><div class="field"><label>Merma (%)</label><input id="prdWaste" type="number" min="0" max="99.999" step="0.001" value="${p?.wastePct??0}"></div><div class="field"><label>Stock mínimo</label><input id="prdMin" type="number" min="0" step="0.001" value="${p?.minQty??p?.min??0}"></div><div class="field"><label>Stock máximo</label><input id="prdMax" type="number" min="0" step="0.001" value="${p?.maxQty??p?.max??0}"></div><div class="field full"><div id="prdCostSummary" class="resultbox"></div></div></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="save-product" data-id="${esc(id)}">Guardar producto</button></div>`);
 const recalc=()=>{const q=Number(document.getElementById('prdPackQty')?.value||0),price=Number(document.getElementById('prdPackPrice')?.value||0),from=document.getElementById('prdPackUnit')?.value||'unidad',to=document.getElementById('prdStandardUnit')?.value||from,w=Math.min(99.999,Math.max(0,Number(document.getElementById('prdWaste')?.value||0)));let c=q>0?price/q:price;try{if(q>0&&from!==to&&window.LRXCost?.convert)c=window.LRXCost.convert(c,from,to)}catch(e){}const ec=c/(Math.max(.000001,1-w/100));const box=document.getElementById('prdCostSummary');if(box)box.innerHTML=q>0?`Costo estándar: <b>${money(c)}</b> / ${esc(to)} · Rendimiento: <b>${(100-w).toFixed(2)}%</b> · Costo utilizable: <b>${money(ec)}</b> / ${esc(to)}`:'Indica contenido y costo para calcular el costo estándar.'};
 ['prdPackQty','prdPackPrice','prdPackUnit','prdStandardUnit','prdWaste'].forEach(x=>document.getElementById(x)?.addEventListener('input',recalc));recalc();
}
function saveProduct(id=''){
 const name=document.getElementById('prdName')?.value.trim();if(!name)return toast('Indica el nombre del producto');
 const code=document.getElementById('prdCode')?.value.trim()||nextCatalogCode(),barcode=document.getElementById('prdBarcode')?.value.trim()||'',category=document.getElementById('prdCategory')?.value.trim()||'Sin categoría',supplier=document.getElementById('prdSupplier')?.value.trim()||'',purchaseUnit=document.getElementById('prdPurchaseUnit')?.value.trim()||'unidad',packPrice=Number(document.getElementById('prdPackPrice')?.value||0),packQty=Number(document.getElementById('prdPackQty')?.value||0),packUnit=document.getElementById('prdPackUnit')?.value||purchaseUnit,standardUnit=document.getElementById('prdStandardUnit')?.value||packUnit,waste=Math.min(99.999,Math.max(0,Number(document.getElementById('prdWaste')?.value||0))),minQty=Number(document.getElementById('prdMin')?.value||0),maxQty=Number(document.getElementById('prdMax')?.value||0),norm=v=>String(v||'').trim().toLowerCase();
 let p=id?state.products.find(x=>String(x.id)===String(id)):null;
 if(!p&&id&&(master.products||[]).some(x=>String(x.id)===String(id)))p=cloneMasterProduct(id);
 const originId=String(p?.masterId||'');
 const all=[...(master.products||[]),...(state.products||[])],codeDup=all.find(x=>String(x.id)!==String(id)&&(code&&[x.code,x.sku,x.itemCode,x.upc,x.barcode,x.id].some(v=>String(v||'').trim().toLowerCase()===code.toLowerCase()))),nameDup=all.find(x=>String(x.id)!==String(id)&&String(x.id)!==originId&&norm(x.name)===norm(name));
 if(codeDup)return toast(`Ese código ya pertenece a ${codeDup.name||codeDup.id}.`);
 if(nameDup)return toast(`Ya existe otro producto con el nombre “${nameDup.name||name}”.`);
 if(!Number.isFinite(packPrice)||packPrice<0||!Number.isFinite(packQty)||packQty<0||!Number.isFinite(waste)||waste<0||waste>=100||!Number.isFinite(minQty)||minQty<0||!Number.isFinite(maxQty)||maxQty<0||(maxQty>0&&maxQty<minQty))return toast('Revisa costo, presentación, merma y mínimos/máximos.');
 let c=packQty>0?packPrice/packQty:packPrice;try{if(packQty>0&&packUnit!==standardUnit&&window.LRXCost?.convert)c=window.LRXCost.convert(c,packUnit,standardUnit)}catch(e){return toast('No se pudo convertir la unidad seleccionada.')}
 const effective=c/Math.max(.000001,1-waste/100);if(!Number.isFinite(effective))return toast('No se pudo calcular el costo unitario.');
 const snapshot=JSON.stringify(state);
 try{
  if(!p){p={id:id||nextCatalogCode(),createdAt:now(),source:'LOCAL'};state.products.push(p)}
  Object.assign(p,{code,sku:code,barcode,upc:barcode,category,supplier,purchaseUnit,packPrice,purchasePrice:packPrice,packQty,packUnit,unit:standardUnit,standardUnit,preMermaUnitCost:c,standardUnitCost:c,cost:effective,finalCost:effective,usableCost:effective,wastePct:waste,yieldFactor:1-waste/100,minQty,maxQty,updatedAt:now()});
  audit('PRODUCT_EDIT',`${name} · ${p.id}`);
  try{reconcileInventoryFromPurchases()}catch(e){console.warn('LRX purchase reconciliation after product save',e)}
  if(!save()){restoreStateSnapshot(snapshot);return}
  close();render();toast('Producto guardado correctamente')
 }catch(e){restoreStateSnapshot(snapshot);toast('No se guardó el producto; conserva la ventana abierta e inténtalo de nuevo.')}
}
function editProduct(id){productModal(id)}
function duplicateProduct(id){const base=productRecordById(id);if(!base)return toast('No se encontró el producto para duplicar.');const snapshot=JSON.stringify(state);try{const copy=JSON.parse(JSON.stringify(base));copy.id='PROD-COPY-'+Date.now()+'-'+Math.random().toString(36).slice(2,6);copy.source='LOCAL';copy.name=String(base.name||'Producto')+' (copia)';copy.code='COPY-'+Date.now();copy.sku=copy.code;copy.barcode='';copy.upc='';copy.masterId=String(base.id);delete copy.photo;delete copy.attachments;copy.createdAt=now();copy.updatedAt=now();state.products=Array.isArray(state.products)?state.products:[];state.products.unshift(copy);audit('PRODUCT_DUPLICATE',`${base.id} → ${copy.id} · ${copy.name}`);if(!save()){restoreStateSnapshot(snapshot);return}render();toast('Producto duplicado. Edita la copia para cambiar sus datos.')}catch(e){restoreStateSnapshot(snapshot);toast('No se pudo duplicar el producto; los datos originales siguen intactos.')}}
function deleteProduct(id){const p=state.products.find(x=>String(x.id)===String(id));if(!p)return toast('El producto maestro no se elimina desde aquí. Puedes editarlo para crear una versión local.');if(!confirm(`¿Eliminar el producto “${p.name}”?`))return;const used=(state.purchases||[]).some(x=>String(x.productId||'')===String(id))||(state.inventory||[]).some(x=>String(x.productId||'')===String(id))||(state.recipes||[]).some(r=>(r.items||[]).some(i=>String(i.productId||'')===String(id)));if(used)return toast('No se puede eliminar: el producto tiene compras, inventario o recetas vinculadas.');state.products=state.products.filter(x=>String(x.id)!==String(id));save();render();toast('Producto eliminado')}
