function saveSupplier(id=''){const name=document.getElementById('sn')?.value.trim();if(!name)return toast('Indica el nombre del proveedor');const norm=v=>String(v||'').trim().toLowerCase();const dup=[...(master.suppliers||[]),...(state.suppliers||[])].map((x,i)=>typeof x==='string'?{id:'SUPP-'+String(i+1).padStart(3,'0'),name:x}:x).find(x=>String(x.id)!==String(id)&&norm(x.name)===norm(name));if(dup)return toast(`El proveedor ya existe: ${dup.name}`);const old=(state.suppliers||[]).find(x=>String(x.id)===String(id));if(id&&!old)return toast('No se encontró el proveedor para editar.');const snapshot=JSON.stringify(state);let s=old;if(!s){s={id:id&&String(id).startsWith('SUPP-')?id:nextSupplierCode(),source:'LOCAL',createdAt:now()};state.suppliers=[...(state.suppliers||[]),s]}Object.assign(s,{name,contact:document.getElementById('sc')?.value.trim()||'',phone:document.getElementById('sp')?.value.trim()||'',email:document.getElementById('se')?.value.trim()||'',terms:document.getElementById('st')?.value.trim()||'',notes:document.getElementById('sx')?.value.trim()||'',updatedAt:now()});audit(old?'SUPPLIER_EDIT':'SUPPLIER_CREATE',`${name} · ${s.id}`);if(!save()){restoreStateSnapshot(snapshot);return}close();render();toast('Proveedor guardado')}
