function saveDateRange(){
 const from=document.getElementById('dateFrom')?.value||'',to=document.getElementById('dateTo')?.value||'';
 const validDate=v=>/^\d{4}-\d{2}-\d{2}$/.test(v)&&Number.isFinite(new Date(v+'T12:00:00').getTime())&&new Date(v+'T12:00:00').toISOString().slice(0,10)===v;
 if(!validDate(from)||!validDate(to))return toast('Selecciona dos fechas válidas.');
 if(from>to)return toast('La fecha inicial no puede ser posterior a la fecha final');
 const snapshot=JSON.stringify(state);state.settings=state.settings||{};state.settings.dateRange={from,to};const ok=save();if(!ok){restoreStateSnapshot(snapshot);return}try{localStorage.setItem('lrx_ui_date_range_preference',JSON.stringify({from,to}))}catch(e){console.warn('Could not persist date range preference',e)}close();updateDateChip();render();toast('Rango de fechas actualizado y guardado');
}
function saveDocumentFromFile(file,opts={}){
 if(!file)return;
 const max=8*1024*1024;if(file.size>max)return toast('El archivo supera 8 MB. Reduce el tamaño antes de guardarlo.');
 const reader=new FileReader();
 reader.onload=async()=>{
  try{
   let ocrText='';
   try{ocrText=await readPurchaseDocument(file)}catch(e){ocrText=''}
   const snapshot=JSON.stringify(state);
   state.documents=Array.isArray(state.documents)?state.documents:[];
   const id='DOC-'+Date.now();
   state.documents.unshift({id,name:file.name,type:opts.type||'Documento',description:opts.description||`Documento capturado en ${opts.module||current}`,mime:file.type||'application/octet-stream',size:file.size,dataUrl:String(reader.result||''),ocrText:String(ocrText||''),routeArea:opts.routeArea||opts.module||current,routeCollection:opts.contextCollection||'documents',contextModule:opts.module||current,contextRecordId:opts.contextRecordId||'',createdAt:now(),createdBy:currentUser().name});
   audit('DOCUMENTO_GUARDADO',`${id} · ${file.name} · ${opts.module||current}`);
   if(!save()){restoreStateSnapshot(snapshot);return}
   close();render();toast(ocrText?'Documento guardado con OCR':'Documento guardado');
  }catch(e){console.error(e);toast('No se pudo guardar el documento')}
 };
 reader.onerror=()=>toast('No se pudo leer el archivo. Sigue disponible para volver a intentarlo.');
 reader.readAsDataURL(file);
}
function cameraCapture(callback){
 const finish=f=>{if(typeof callback==='function')callback(f);else saveDocumentFromFile(f,{type:'Fotografía',module:current,routeArea:current})};
 if(!navigator.mediaDevices?.getUserMedia){
   const input=document.createElement('input');input.type='file';input.accept='image/*';input.style.display='none';document.body.appendChild(input);
   input.onchange=()=>{const f=input.files?.[0];input.remove();if(f)finish(f)};input.click();return;
 }
 modal(`<h3>Tomar fotografía</h3><p class="muted">Permite el acceso a la cámara para tomar la foto directamente desde LRX.</p><div class="camera-box" style="background:#111;border-radius:14px;padding:10px"><video id="lrxCameraVideo" autoplay playsinline muted style="width:100%;max-height:58vh;object-fit:contain;border-radius:10px;background:#000"></video></div><canvas id="lrxCameraCanvas" hidden></canvas><div id="cameraStatus" class="resultbox" style="margin-top:10px">Iniciando cámara…</div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn" id="cameraFallback">📎 Elegir archivo</button><button class="btn primary" id="cameraTake">📷 Tomar foto</button></div>`);
 const video=document.getElementById('lrxCameraVideo'),status=document.getElementById('cameraStatus');
 const fallback=()=>{stopCameraStream();const input=document.createElement('input');input.type='file';input.accept='image/*';input.style.display='none';document.body.appendChild(input);input.onchange=()=>{const f=input.files?.[0];input.remove();if(f){close();finish(f)}};input.click()};
 document.getElementById('cameraFallback')?.addEventListener('click',fallback);
 navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:1080}},audio:false}).then(stream=>{
   activeCameraStream=stream;video.srcObject=stream;status.textContent='Cámara activa. Encuadra y pulsa “Tomar foto”.';
 }).catch(err=>{status.textContent='No se pudo abrir la cámara. Puedes elegir una foto del dispositivo.';console.warn('LRX camera',err);document.getElementById('cameraTake')?.setAttribute('disabled','true')});
 document.getElementById('cameraTake')?.addEventListener('click',()=>{
   if(!activeCameraStream||!video.videoWidth)return toast('La cámara todavía no está lista.');
   const canvas=document.getElementById('lrxCameraCanvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);
   canvas.toBlob(blob=>{if(!blob)return toast('No se pudo capturar la fotografía.');const f=new File([blob],`LRX-foto-${Date.now()}.jpg`,{type:'image/jpeg'});stopCameraStream();close();finish(f)},'image/jpeg',0.92);
 });
} 
function captureDocumentsModal(contextModule=current,opts={}){
 const mod=contextModule||current;
 modal(`<h3>Capturar / importar documento</h3><p class="muted">El documento quedará asociado al módulo <b>${esc(mod)}</b>. El OCR es automático cuando el formato es compatible.</p><div class="formgrid"><div class="field full"><label>Archivo</label><input id="docCaptureFile" type="file" accept="image/*,application/pdf,.txt,.csv"></div><div class="field"><label>Tipo</label><select id="docCaptureType"><option>Documento</option><option>Factura</option><option>Recibo</option><option>Fotografía</option><option>Ficha técnica</option><option>Otro</option></select></div><div class="field"><label>Área / módulo</label><input id="docCaptureArea" value="${esc(mod)}"></div></div><div id="docCaptureStatus" class="resultbox">Selecciona un archivo.</div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn" id="docCameraBtn">📷 Fotografiar</button><button class="btn primary" id="docSaveBtn">Guardar documento + OCR</button></div>`);
 document.getElementById('docCameraBtn')?.addEventListener('click',()=>cameraCapture(f=>{const inp=document.getElementById('docCaptureFile');const dt=new DataTransfer();dt.items.add(f);inp.files=dt.files;document.getElementById('docCaptureStatus').textContent=`📷 ${f.name}`;}));
 document.getElementById('docCaptureFile')?.addEventListener('change',e=>{const f=e.target.files?.[0];if(f)document.getElementById('docCaptureStatus').textContent=`📎 ${f.name}`});
 document.getElementById('docSaveBtn')?.addEventListener('click',()=>{const f=document.getElementById('docCaptureFile')?.files?.[0];if(!f)return toast('Selecciona un archivo');saveDocumentFromFile(f,{type:document.getElementById('docCaptureType')?.value||'Documento',module:document.getElementById('docCaptureArea')?.value.trim()||mod,routeArea:document.getElementById('docCaptureArea')?.value.trim()||mod,contextCollection:opts.contextCollection||'documents',contextRecordId:opts.contextRecordId||''})});
}
function voiceAction(){
 const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;
 modal(`<h3>Control por voz</h3><p class="muted">La voz se usa únicamente para navegar. No llenará formularios.</p><div id="voiceStatus" class="resultbox">Pulsa “Escuchar” y di el nombre de un módulo.</div><div class="actions"><button class="btn" data-action="close">Cerrar</button><button class="btn primary" id="voiceListen">🎙️ Escuchar</button></div>`);
 const status=document.getElementById('voiceStatus');
 if(!Speech){status.textContent='El navegador no ofrece reconocimiento de voz en este momento.';return;}
 document.getElementById('voiceListen').onclick=()=>{const r=new Speech();r.lang='es-US';r.interimResults=false;r.maxAlternatives=3;status.textContent='Escuchando…';r.onresult=e=>{const heard=[...e.results].map(x=>x[0].transcript).join(' ').toLowerCase().trim();const hit=MODULES.find(m=>m.slice(0,3).join(' ').toLowerCase().includes(heard))||MODULES.find(m=>m.some(v=>String(v).toLowerCase().includes(heard)));if(hit){close();go(hit[0]);toast('Navegando a '+hit[1])}else status.textContent=`No encontré un módulo para “${heard}”.`;};r.onerror=()=>status.textContent='No se pudo reconocer la voz. Intenta nuevamente.';r.onend=()=>{if(status.textContent==='Escuchando…')status.textContent='Listo para escuchar nuevamente.'};r.start();};
}

/* ===== LRX v203 · Centro universal de archivos ===== */
function fileExt(name=''){const m=String(name).toLowerCase().match(/\.([a-z0-9]+)$/);return m?m[1]:''}
function fileIsImage(a){return String(a?.type||'').toLowerCase().startsWith('image/')||/\.(png|jpe?g|gif|webp|bmp|svg)$/i.test(a?.name||'')}
function fileIsPdf(a){return String(a?.type||'').toLowerCase()==='application/pdf'||/\.pdf$/i.test(a?.name||'')}
function fileIsText(a){return String(a?.type||'').toLowerCase().startsWith('text/')||/\.(txt|csv|json|xml|md)$/i.test(a?.name||'')}
function fileDownload(a,auditCode='FILE_DOWNLOAD',detail='Archivo descargado'){
 if(!a?.dataUrl)return toast('Este archivo no tiene contenido local disponible.');
 const link=document.createElement('a');link.href=a.dataUrl;link.download=a.name||'archivo';document.body.appendChild(link);link.click();link.remove();audit(auditCode,`${detail}: ${a.name||'archivo'}`)
}
function filePrint(a,title='Documento'){
 if(!a?.dataUrl)return toast('Este archivo no tiene contenido local disponible.');
 const type=String(a.type||'').toLowerCase();
 if(fileIsImage(a)||fileIsPdf(a)){
  const w=window.open('','_blank');
  if(!w)return toast('Safari bloqueó la ventana de impresión. Permite ventanas emergentes para LRX.');
  const src=String(a.dataUrl);
  if(fileIsImage(a)) w.document.write(`<html><head><title>${esc(a.name||title)}</title></head><body style="margin:0;display:flex;justify-content:center;align-items:flex-start"><img src="${src}" style="max-width:100%;height:auto" onload="window.print()"></body></html>`);
  else w.document.write(`<html><head><title>${esc(a.name||title)}</title></head><body style="margin:0"><iframe src="${src}" style="border:0;width:100vw;height:100vh" onload="window.print()"></iframe></body></html>`);
  w.document.close();audit('FILE_PRINT',`Impreso: ${a.name||title}`);return;
 }
 if(fileIsText(a)){
  let raw='';try{raw=atob(String(a.dataUrl).split(',')[1]||'')}catch(e){raw='No se pudo leer el contenido de texto.'}
  return printHtml(title,`<h2>${esc(a.name||'Archivo')}</h2><pre style="white-space:pre-wrap">${esc(raw)}</pre>`)
 }
 printHtml(title,`<h2>${esc(a.name||'Archivo')}</h2><p>Archivo adjunto: ${esc(a.name||'Archivo')}</p><p>Este formato no dispone de una vista previa nativa en Safari.</p>`)
}
function filePreviewModal(a,{title='Vista previa',source='Documento',onDownload=null,onDelete=null,allowDelete=false}={}){
 if(!a?.dataUrl)return toast('Archivo no disponible.');
 const type=String(a.type||'').toLowerCase();let content='';
 if(fileIsImage(a)) content=`<div style="display:flex;justify-content:center;align-items:center;min-height:240px;background:#f7f8fb;border:1px solid var(--line);border-radius:12px;padding:12px"><img src="${a.dataUrl}" alt="${esc(a.name||'Archivo')}" style="max-width:100%;max-height:64vh;object-fit:contain"></div>`;
 else if(fileIsPdf(a)) content=`<iframe src="${a.dataUrl}" title="${esc(a.name||'PDF')}" style="width:100%;height:64vh;border:1px solid var(--line);border-radius:12px;background:#fff"></iframe>`;
 else if(fileIsText(a)) {let raw='';try{raw=atob(String(a.dataUrl).split(',')[1]||'')}catch(e){raw='No se pudo decodificar este archivo.'}content=`<pre style="white-space:pre-wrap;max-height:64vh;overflow:auto;padding:16px;background:#fff;border:1px solid var(--line);border-radius:12px">${esc(raw)}</pre>`}
 else content=`<div class="card" style="padding:28px;text-align:center"><div style="font-size:48px">📄</div><h3>${esc(a.name||'Archivo')}</h3><p class="muted">${esc(type||'Formato')} · ${Number(a.size||0)?Math.max(1,Math.round(Number(a.size)/1024))+' KB':'tamaño no disponible'}</p><p>Este formato no tiene vista previa nativa en Safari. Puedes descargarlo, exportarlo o imprimir su ficha.</p></div>`;
 const extra=allowDelete&&onDelete?`<button class="btn danger" id="universalDeleteFile">Eliminar</button>`:'';
 modal(`<h3>${esc(title)} · ${esc(a.name||'Archivo')}</h3><p class="muted">Origen: ${esc(source)}</p>${content}<div class="actions"><button class="btn" data-action="close">Cerrar</button><button class="btn" id="universalDownloadFile">⬇ Descargar</button><button class="btn" id="universalExportFile">⇩ Exportar</button><button class="btn primary" id="universalPrintFile">🖨 Imprimir</button>${extra}</div>`);
 document.getElementById('universalDownloadFile')?.addEventListener('click',()=>onDownload?onDownload():fileDownload(a,'FILE_DOWNLOAD',`Descargado desde ${source}`));
 document.getElementById('universalExportFile')?.addEventListener('click',()=>fileDownload(a,'FILE_EXPORT',`Exportado desde ${source}`));
 document.getElementById('universalPrintFile')?.addEventListener('click',()=>filePrint(a,source));
 document.getElementById('universalDeleteFile')?.addEventListener('click',()=>onDelete&&onDelete());
}
function documentPreview(id){const d=(state.documents||[]).find(x=>String(x.id)===String(id));if(!d)return toast('Documento no encontrado.');filePreviewModal(d,{title:'Vista previa',source:d.routeArea||d.contextModule||'Documentos'});audit('DOCUMENT_PREVIEW',`Vista previa: ${d.name||d.id}`)}

