function saveEmployee(id=''){
 const g=x=>document.getElementById(x)?.value?.trim()||''; const name=g('empName'); if(!name)return toast('El nombre completo es obligatorio.');const compensation=Number(g('empComp')||0);if(!Number.isFinite(compensation)||compensation<0)return toast('El pago debe ser un monto igual o mayor que cero.');
 const arr=Array.isArray(state.employees)?state.employees:[]; let e=id?employeeById(id):null; const employeeId=e?.id||g('empId')||'EMP-'+Date.now();if(!e&&arr.some(x=>String(x.id).toLowerCase()===String(employeeId).toLowerCase()))return toast('Ese ID de empleado ya existe.');const snapshot=JSON.stringify(state);
 if(!e){e={id:employeeId,createdAt:now(),attachments:[]};arr.push(e)}
 Object.assign(e,{name,preferredName:g('empPreferred'),phone:g('empPhone'),email:g('empEmail'),address:g('empAddress'),birthDate:g('empBirth'),hireDate:g('empHire'),department:g('empDept'),position:g('empPosition'),payType:g('empPayType')||'Hora',compensation,emergencyName:g('empEmergency'),emergencyPhone:g('empEmergencyPhone'),emergencyRelation:g('empEmergencyRel'),status:g('empStatus')||'ACTIVO',notes:document.getElementById('empNotes')?.value||'',updatedAt:now()});
 const role=g('empUserRole'), userName=g('empUserName')||name, view=document.getElementById('empDigitalView')?.checked===true;
 if(role){let u=e.userId?(state.users||[]).find(x=>String(x.id)===String(e.userId)):null;if(!u){u={id:'USR-'+employeeId,name:userName,role,active:e.status==='ACTIVO',createdAt:now()};state.users.push(u)}Object.assign(u,{name:userName,role,active:e.status==='ACTIVO',digitalCredentialView:view,employeeId:employeeId,updatedAt:now()});e.userId=u.id;e.userName=u.name}else if(e.userId){const u=state.users.find(x=>String(x.id)===String(e.userId));if(u&&u.id!=='USR-ADMIN')u.active=false;e.userId='';e.userName=''}
 const files=[...(document.getElementById('empFiles')?.files||[])]; const photo=document.getElementById('empPhoto')?.files?.[0]; if(photo)files.push(photo);if(files.some(f=>f.size>8*1024*1024)){restoreStateSnapshot(snapshot);return toast('Un archivo supera 8 MB. No se guardó la ficha; reduce el archivo o adjúntalo por separado.')}
 const readFile=f=>new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=()=>reject(new Error('No se pudo leer '+f.name));fr.readAsDataURL(f)});
 const compressImage=async f=>{if(!f.type.startsWith('image/'))return {dataUrl:await readFile(f),type:f.type,size:f.size};const src=await readFile(f);const img=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('No se pudo procesar '+f.name));im.src=src});const scale=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return {dataUrl:canvas.toDataURL('image/jpeg',.78),type:'image/jpeg',size:Math.ceil(canvas.width*canvas.height*.45)}};
 Promise.all(files.map(async f=>{const data=await compressImage(f);return {name:f.name,type:data.type,size:data.size,dataUrl:data.dataUrl,addedAt:now(),kind:(photo&&f===photo)?'photo':'document'}})).then(out=>{for(const a of out){if(a.kind==='photo')e.photo=a;else e.attachments=[...(e.attachments||[]),a]}state.employees=arr;audit(id?'EMPLOYEE_EDIT':'EMPLOYEE_CREATE',`${id?'Editado':'Creado'} empleado ${e.id} · ${e.name}`);if(!save()){restoreStateSnapshot(snapshot);return}close();render();toast(role?`Ficha guardada y usuario ${e.userId} vinculado.`:'Ficha de empleado guardada.')}).catch(()=>{restoreStateSnapshot(snapshot);toast('No se pudo leer o procesar un archivo. Los cambios no se guardaron.')});
}
