/* ===== LRX DIGITAL ASSETS — secure registry ===== */
function digitalAssetById(id){return (state.digitalAssets||[]).find(x=>String(x.id)===String(id))||null}
function digitalCanView(){const u=currentUser();if(SECURE_ROLES.includes(u.role))return true;return (state.digitalAccessRequests||[]).some(x=>String(x.userId)===String(u.id)&&String(x.status)==='APROBADA')}
function digitalAccessRequest(){
 const u=currentUser(); const arr=Array.isArray(state.digitalAccessRequests)?state.digitalAccessRequests:[];
 const existing=arr.find(x=>String(x.userId)===String(u.id)&&x.status==='PENDIENTE');
 if(existing)return toast('Ya tienes una solicitud pendiente.');
 const r={id:'DAR-'+Date.now(),userId:u.id,userName:u.name,role:u.role,requestedAt:now(),status:'PENDIENTE'};const snapshot=JSON.stringify(state);
 arr.push(r);state.digitalAccessRequests=arr;audit('DIGITAL_ACCESS_REQUEST',`Solicitud ${r.id} de ${u.name}`);if(!save()){restoreStateSnapshot(snapshot);return}toast('Solicitud enviada al administrador/responsable.');
 if(current==='activos-digitales')render();
}
function digitalAccessRequestsModal(){
 const me=currentUser(); const all=Array.isArray(state.digitalAccessRequests)?state.digitalAccessRequests:[];
 const canManage=['Admin','Socio','Finanzas','Administración','Gerente General'].includes(me.role);
 const rows=(canManage?all:all.filter(x=>String(x.userId)===String(me.id))).slice().reverse();
 const own=all.find(x=>String(x.userId)===String(me.id)&&x.status==='PENDIENTE');
 modal(`<h3>Solicitudes y permisos · Activos Digitales</h3><p class="muted">Aquí se solicita y aprueba el acceso al módulo y se configura quién puede ver credenciales sin introducir la clave autorizada.</p><div class="actions" style="margin-bottom:10px"><button class="btn primary" data-action="digital-request-access">🔐 ${own?'Ya tienes una solicitud pendiente':'Solicitar autorización'}</button>${me.role==='Admin'?`<button class="btn" data-action="digital-permissions">⚙️ Permisos de credenciales</button><button class="btn" data-action="digital-set-master-pin">🔑 Configurar clave autorizada</button>`:''}</div><div class="tablewrap"><table><thead><tr><th>Solicitud</th><th>Usuario</th><th>Rol</th><th>Fecha</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.userName)}</td><td>${esc(r.role)}</td><td>${fmt(r.requestedAt,true)}</td><td><span class="status">${esc(r.status||'PENDIENTE')}</span></td><td>${canManage&&r.status==='PENDIENTE'?`<button class="btn primary" data-action="digital-approve" data-id="${esc(r.id)}">Aprobar</button> <button class="btn danger" data-action="digital-reject" data-id="${esc(r.id)}">Rechazar</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No hay solicitudes.</td></tr>'}</tbody></table></div><div class="card" style="margin-top:12px"><b>Cómo funciona</b><ol class="small"><li>El empleado/usuario solicita autorización.</li><li>Un administrador o responsable autorizado la aprueba o rechaza.</li><li>Una vez aprobada, el usuario puede entrar al módulo.</li><li>Para ver una contraseña concreta necesita permiso especial o la clave autorizada.</li></ol></div><div class="actions"><button class="btn" data-action="close">Cerrar</button></div>`)
}
function digitalCredentialAllowed(){
 const u=currentUser();
 return SECURE_ROLES.includes(u.role)||u.digitalCredentialView===true;
}
function digitalSetMasterPin(){
 if(currentUser().role!=='Admin')return toast('Solo Admin puede configurar la clave autorizada.');
 const current=state.settings?.digitalCredentialMasterPin||'';
 modal(`<h3>Clave autorizada para credenciales</h3><p class="muted">Esta clave se solicitará cuando un usuario no tenga permiso directo para ver contraseñas.</p><div class="field"><label>Nueva clave autorizada</label><input id="digitalMasterPin" type="password" value="${esc(current)}" autocomplete="new-password"></div><p class="small">La aplicación oculta la clave en pantalla y no la incluye en impresiones.</p><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" id="saveDigitalMasterPin">Guardar clave</button></div>`);
 document.getElementById('saveDigitalMasterPin')?.addEventListener('click',()=>{const pin=document.getElementById('digitalMasterPin')?.value||'';if(pin.length<4)return toast('Usa una clave de al menos 4 caracteres.');const snapshot=JSON.stringify(state);state.settings.digitalCredentialMasterPin=pin;audit('DIGITAL_MASTER_PIN_UPDATE','Se actualizó la clave autorizada de credenciales');if(!save()){restoreStateSnapshot(snapshot);return}close();toast('Clave autorizada actualizada')});
}
function digitalPermissionsModal(){
 if(currentUser().role!=='Admin')return toast('Solo Admin puede configurar permisos.');
 const users=(state.users||[]).filter(u=>u.active!==false);
 modal(`<h3>Permisos para ver credenciales</h3><p class="muted">Los usuarios marcados pueden ver las claves sin escribir la clave autorizada. El acceso al módulo se mantiene separado.</p><div class="tablewrap"><table><thead><tr><th>Usuario</th><th>Rol</th><th>Módulo</th><th>Ver credenciales</th></tr></thead><tbody>${users.map(u=>`<tr><td><b>${esc(u.name||u.id)}</b><br><small>${esc(u.id||'')}</small></td><td>${esc(u.role||'')}</td><td>${digitalCanViewForUser(u)?'AUTORIZADO':'RESTRINGIDO'}</td><td><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" data-digital-user="${esc(u.id)}" ${u.digitalCredentialView===true?'checked':''}> Permitir</label></td></tr>`).join('')}</tbody></table></div><div class="actions"><button class="btn" data-action="close">Cerrar</button><button class="btn primary" id="saveDigitalPermissions">Guardar permisos</button></div>`);
 document.getElementById('saveDigitalPermissions')?.addEventListener('click',()=>{const snapshot=JSON.stringify(state);document.querySelectorAll('[data-digital-user]').forEach(ch=>{const u=state.users.find(x=>String(x.id)===String(ch.dataset.digitalUser));if(u)u.digitalCredentialView=!!ch.checked});audit('DIGITAL_PERMISSION_UPDATE','Se actualizaron permisos individuales para ver credenciales');if(!save()){restoreStateSnapshot(snapshot);return}close();toast('Permisos actualizados');digitalAccessRequestsModal()});
}
function digitalCanViewForUser(u){return !!u&&(SECURE_ROLES.includes(u.role)||u.digitalCredentialView===true||(state.digitalAccessRequests||[]).some(x=>String(x.userId)===String(u.id)&&x.status==='APROBADA'))}
function digitalCredentialPrompt(id,after){
 const r=digitalAssetById(id);if(!r)return;
 if(digitalCredentialAllowed())return after(r);
 const configured=String(state.settings?.digitalCredentialMasterPin||'');
 if(!configured)return toast('No existe una clave autorizada configurada. Un Admin debe configurarla primero.');
 modal(`<h3>Autorización requerida</h3><p>Para ver la clave de <b>${esc(r.name||r.id)}</b> introduce la clave autorizada.</p><div class="field"><label>Clave autorizada</label><input id="digitalRevealPin" type="password" autocomplete="off"></div><div id="digitalRevealError" class="small"></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" id="confirmDigitalReveal">Autorizar y ver</button></div>`);
 document.getElementById('confirmDigitalReveal')?.addEventListener('click',()=>{const pin=document.getElementById('digitalRevealPin')?.value||'';if(pin!==configured){document.getElementById('digitalRevealError').textContent='Clave no autorizada.';audit('DIGITAL_CREDENTIAL_DENIED',`Intento de acceso denegado: ${r.name||r.id}`);return}audit('DIGITAL_CREDENTIAL_AUTHORIZED_VIEW',`Credencial autorizada temporalmente: ${r.name||r.id}`);close();after(r)});
}
function digitalRevealPassword(id){
 const r=digitalAssetById(id);if(!r)return;
 digitalCredentialPrompt(id,(rec)=>{
   const el=document.getElementById('digitalSecret-'+CSS.escape(String(id)));if(!el)return;
   el.textContent=String(rec.password||'')||'(sin clave registrada)';el.dataset.revealed='1';
   setTimeout(()=>{if(el.isConnected){el.textContent='••••••••';el.dataset.revealed='0'}},8000);
 });
}
function digitalCopyPassword(id){
 const r=digitalAssetById(id);if(!r)return;
 digitalCredentialPrompt(id,(rec)=>{
   if(!navigator.clipboard?.writeText)return toast('El navegador no permitió copiar la credencial.');
   navigator.clipboard.writeText(String(rec.password||'')).then(()=>{audit('DIGITAL_CREDENTIAL_COPY',`Credencial copiada: ${rec.name||rec.id}`);toast('Credencial copiada al portapapeles. Se ocultará nuevamente en breve.')}).catch(()=>toast('El navegador no permitió copiar la credencial.'));
 });
}
function digitalPreviewAttachment(id,index){
 const r=digitalAssetById(id),a=r?.attachments?.[Number(index)];if(!a?.dataUrl)return toast('Archivo no disponible.');
 const mime=String(a.type||'').toLowerCase(),name=String(a.name||'archivo');
 let body='';
 if(mime.startsWith('image/')) body=`<div style="text-align:center;background:#f6f7f9;padding:12px;border-radius:12px"><img src="${a.dataUrl}" alt="${esc(name)}" style="max-width:100%;max-height:65vh;object-fit:contain"></div>`;
 else if(mime==='application/pdf'||/\.pdf$/i.test(name)) body=`<iframe src="${a.dataUrl}" title="${esc(name)}" style="width:100%;height:65vh;border:1px solid var(--line);border-radius:10px;background:#fff"></iframe>`;
 else if(mime.startsWith('text/')||/\.(txt|csv)$/i.test(name)){let raw='';try{raw=atob(String(a.dataUrl).split(',')[1]||'')}catch(e){}body=`<pre style="max-height:65vh;overflow:auto;white-space:pre-wrap;background:#f6f7f9;padding:14px;border-radius:10px">${esc(raw.slice(0,20000))}</pre>`}
 else body=`<div class="resultbox"><b>${esc(name)}</b><p>Este formato no tiene vista previa nativa en Safari.</p><p class="muted">Puedes descargarlo para abrirlo con su aplicación correspondiente.</p></div>`;
 modal(`<h3>Vista previa · ${esc(name)}</h3><p class="muted">${esc(r.name||r.id)}</p>${body}<div class="actions"><button class="btn" data-action="close">Cerrar</button><button class="btn" id="digitalPreviewPrint">🖨 Imprimir</button><button class="btn primary" id="digitalPreviewDownload">⬇ Descargar</button></div>`);
 document.getElementById('digitalPreviewDownload')?.addEventListener('click',()=>digitalDownloadAttachment(id,index));
 document.getElementById('digitalPreviewPrint')?.addEventListener('click',()=>digitalPrintAttachment(id,index));
}
function digitalPrintAttachment(id,index){
 const r=digitalAssetById(id),a=r?.attachments?.[Number(index)];if(!a?.dataUrl)return toast('Archivo no disponible.');
 const mime=String(a.type||'').toLowerCase();
 if(mime.startsWith('image/')){const w=window.open('','_blank');if(!w)return toast('Safari bloqueó la ventana de impresión.');w.document.write(`<html><head><title>${esc(a.name)}</title><style>@page{margin:0}html,body{margin:0;background:#fff}img{display:block;max-width:100%;width:100%;height:auto}</style></head><body><img src="${a.dataUrl}" onload="window.print()"></body></html>`);w.document.close();return}
 if(mime==='application/pdf'||/\.pdf$/i.test(a.name||'')){const w=window.open(a.dataUrl,'_blank');if(!w)return toast('Safari bloqueó la vista del documento.');audit('DIGITAL_ATTACHMENT_PRINT',`Vista para imprimir: ${a.name}`);return}
 toast('Este formato no permite impresión directa desde la vista previa.');
}
