function saveShoppingItem(id=''){const product=document.getElementById('shProduct')?.value.trim();if(!product)return toast('Indica el producto');const qty=Number(document.getElementById('shQty')?.value||0);if(!Number.isFinite(qty)||qty<0)return toast('La cantidad debe ser un número igual o mayor que cero');const snapshot=JSON.stringify(state),arr=state.shopping||[],old=arr.find(x=>String(x.id)===String(id)),obj={...(old||{}),id:old?.id||'SHOP-'+Date.now(),product,qty,unit:document.getElementById('shUnit')?.value.trim()||'unidad',supplier:document.getElementById('shSupplier')?.value.trim()||'',priority:document.getElementById('shPriority')?.value||'Normal',notes:document.getElementById('shNotes')?.value.trim()||'',done:old?.done||false,createdAt:old?.createdAt||now(),updatedAt:now()};state.shopping=old?arr.map(x=>x.id===old.id?obj:x):[obj,...arr];audit(old?'COMPRA_LISTA_EDITADA':'COMPRA_LISTA_CREADA',`${product} · ${qty} ${obj.unit}`);if(!save()){restoreStateSnapshot(snapshot);return}close();render();toast('Lista de compras actualizada')}
function checklistsModule(){const rows=localSearch(state.checklistTasks||[],'_checkQ'),pending=rows.filter(x=>!x.done),done=rows.filter(x=>x.done);return head('Checklists','Tareas de apertura, cierre, limpieza, seguridad y operación.',`<button class="btn primary" data-action="check-new">＋ Nueva tarea</button> <button class="btn" data-action="check-template">＋ Cargar tareas iniciales</button> <button class="btn" data-action="check-export">Excel + CSV</button> <button class="btn" data-action="check-print">Imprimir / PDF</button>`)+`<div class="grid"><div class="card kpi"><small>Pendientes</small><strong>${pending.length}</strong></div><div class="card kpi"><small>Completadas</small><strong>${done.length}</strong></div></div><div class="card" style="margin-top:14px"><div class="toolbar"><input id="checkQ" class="input search" value="${esc(state._checkQ||'')}" placeholder="Buscar tarea, área o responsable"><select id="checkFilter"><option value="all">Todas</option><option value="pending" ${state._checkFilter==='pending'?'selected':''}>Pendientes</option><option value="done" ${state._checkFilter==='done'?'selected':''}>Completadas</option></select></div>${rowsTable([['Tarea'],['Área'],['Turno'],['Responsable'],['Fecha'],['Estado']],(state._checkFilter==='pending'?pending:state._checkFilter==='done'?done:rows).slice().sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))).map(x=>`<tr><td><b>${esc(x.title||x.task)}</b><small>${esc(x.notes||'')}</small></td><td>${esc(x.area||'—')}</td><td>${esc(x.shift||'—')}</td><td>${esc(x.assignee||'—')}</td><td>${esc(x.date||'—')}</td><td><span class="status">${x.done?'COMPLETADA':'PENDIENTE'}</span></td><td><button class="btn" data-action="check-toggle" data-id="${esc(x.id)}">${x.done?'Desmarcar':'Completar'}</button> <button class="btn" data-action="check-edit" data-id="${esc(x.id)}">Editar</button> <button class="btn danger" data-action="check-delete" data-id="${esc(x.id)}">Eliminar</button></td></tr>`).join(''),'No hay tareas de checklist.')}</div>`}
