function permitsModule(){const rows=localSearch(state.permits||[],'_permitsQ'),near=rows.filter(x=>{if(!x.expiryDate)return false;return Math.ceil((new Date(x.expiryDate+'T23:59:59')-Date.now())/86400000)<=30});return head('Documentos y Permisos','Controla permisos, licencias, responsables y vencimientos; los avisos próximos ya se reflejan en alertas.',`<button class="btn primary" data-action="permit-new">＋ Registrar documento</button> <button class="btn" data-action="permit-export">Excel + CSV</button> <button class="btn" data-action="permit-print">Imprimir / PDF</button>`)+`<div class="grid"><div class="card kpi"><small>Documentos / permisos</small><strong>${rows.length}</strong></div><div class="card kpi"><small>Vencidos o vencen pronto</small><strong>${near.length}</strong></div></div><div class="card" style="margin-top:14px"><div class="toolbar"><input id="permitQ" class="input search" value="${esc(state._permitsQ||'')}" placeholder="Buscar documento, entidad o responsable"></div>${rowsTable([['Documento'],['Tipo'],['Entidad'],['Responsable'],['Vencimiento'],['Estado']],rows.slice().sort((a,b)=>String(a.expiryDate||'9999').localeCompare(String(b.expiryDate||'9999'))).map(x=>`<tr><td><b>${esc(x.name||x.title||'—')}</b><small>${esc(x.notes||'')}</small></td><td>${esc(x.type||'—')}</td><td>${esc(x.issuer||'—')}</td><td>${esc(x.owner||'—')}</td><td>${esc(x.expiryDate||'—')}</td><td><span class="status">${esc(x.status||'ACTIVO')}</span></td><td><button class="btn" data-action="permit-edit" data-id="${esc(x.id)}">Editar</button> <button class="btn danger" data-action="permit-delete" data-id="${esc(x.id)}">Eliminar</button></td></tr>`).join(''),'No hay documentos o permisos registrados.')}</div>`}
function permitModal(id=''){
 const r=(state.permits||[]).find(x=>String(x.id)===String(id));
 const attached=(state.documents||[]).filter(x=>String(x.contextRecordId||x.permitId||'')===String(id)&&String(x.contextModule||'')==='documentos-permisos');
 modal(`<h3>${r?'Editar':'Registrar'} documento o permiso</h3><div class="formgrid"><div class="field full"><label>Nombre *</label><input id="pmName" value="${esc(r?.name||'')}"></div><div class="field"><label>Tipo</label><select id="pmType">${(state.settings.nasDocumentTypes||['Licencia','Permiso','Certificado','Contrato','Seguro','Otro']).map(v=>`<option ${r?.type===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label>Entidad emisora</label><input id="pmIssuer" value="${esc(r?.issuer||'')}"></div><div class="field"><label>Responsable</label><input id="pmOwner" value="${esc(r?.owner||'')}"></div><div class="field"><label>Vencimiento</label><input id="pmExpiry" type="date" value="${esc(r?.expiryDate||'')}"></div><div class="field"><label>Estado</label><select id="pmStatus">${['ACTIVO','EN TRÁMITE','PENDIENTE','VENCIDO','ARCHIVADO'].map(v=>`<option ${String(r?.status||'ACTIVO')===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field full"><label>Notas / referencia</label><textarea id="pmNotes">${esc(r?.notes||'')}</textarea></div><div class="field full"><label>Adjuntar documento o foto</label><input id="pmFiles" type="file" multiple accept="image/*,application/pdf,.pdf,.doc,.docx,.txt,.csv"><small class="muted">Se guardará junto con este permiso. Máximo 8 MB por archivo.</small><div id="pmFileStatus" class="resultbox" style="margin-top:8px">${attached.length?`${attached.length} archivo(s) asociado(s)`: 'Sin archivos asociados.'}</div>${attached.map((a,i)=>`<div class="rowhead"><span>📎 ${esc(a.name||'Archivo')}</span><button class="btn" data-action="document-download" data-id="${esc(a.id)}">Descargar</button></div>`).join('')}</div></div><div class="actions"><button class="btn" id="pmPhotoBtn" type="button">📷 Fotografiar</button><input id="pmCameraInput" type="file" accept="image/*" capture="environment" hidden><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="permit-save" data-id="${esc(id)}">Guardar</button></div>`);
 const input=document.getElementById('pmFiles'),status=document.getElementById('pmFileStatus');
 input?.addEventListener('change',()=>{const files=[...(input.files||[])];if(status)status.textContent=files.length?`${files.length} archivo(s) seleccionado(s) · ${files.map(f=>f.name).join(', ')}`:(attached.length?`${attached.length} archivo(s) asociado(s)`:'Sin archivos asociados.');const name=document.getElementById('pmName');if(name&&!name.value.trim()&&files.length)name.value=files[0].name.replace(/\.[^.]+$/,'')});
 const cam=document.getElementById('pmCameraInput');document.getElementById('pmPhotoBtn')?.addEventListener('click',()=>cam?.click());cam?.addEventListener('change',()=>{const files=[...(input?.files||[]),...(cam.files||[])];try{const dt=new DataTransfer();files.forEach(f=>dt.items.add(f));if(input)input.files=dt.files;if(status)status.textContent=`${files.length} archivo(s) seleccionado(s) · ${files.map(f=>f.name).join(', ')}`}catch(e){toast('No se pudo adjuntar la foto. Usa “Seleccionar archivo”.')}});
}
async function savePermit(id=''){
 const name=document.getElementById('pmName')?.value.trim();if(!name)return toast('Indica el nombre del documento');
 const arr=state.permits||[],old=arr.find(x=>String(x.id)===String(id)),expiryDate=document.getElementById('pmExpiry')?.value||'';
 if(id&&!old)return toast('No se encontró el documento para editar.');
 if(expiryDate&&(!/^\d{4}-\d{2}-\d{2}$/.test(expiryDate)||!Number.isFinite(new Date(expiryDate+'T12:00:00').getTime())||new Date(expiryDate+'T12:00:00').toISOString().slice(0,10)!==expiryDate))return toast('Revisa la fecha de vencimiento.');
 const files=[...(document.getElementById('pmFiles')?.files||[])];if(files.some(f=>f.size>8*1024*1024))return toast('Cada archivo debe pesar 8 MB o menos. No se guardaron cambios.');
 let attachments=[];try{if(files.length){attachments=await Promise.all(files.map(readFileDataV207));if(attachments.some(x=>!x?.dataUrl))return toast('No se pudo leer algún archivo. No se guardó el permiso ni se omitieron adjuntos.');attachments=await Promise.all(attachments.map(async(a,i)=>{let ocrText='';try{ocrText=await readPurchaseDocument(files[i])||''}catch(e){}return {...a,ocrText}}))}}catch(e){return toast('No se pudieron leer los archivos. No se guardó el permiso.');}
 const permitId=old?.id||'PERM-'+Date.now(),obj={...(old||{}),id:permitId,name,type:document.getElementById('pmType')?.value||'Otro',issuer:document.getElementById('pmIssuer')?.value.trim()||'',owner:document.getElementById('pmOwner')?.value.trim()||'',expiryDate,status:document.getElementById('pmStatus')?.value||'ACTIVO',notes:document.getElementById('pmNotes')?.value.trim()||'',createdAt:old?.createdAt||now(),updatedAt:now()},snapshot=JSON.stringify(state);
 state.permits=old?arr.map(x=>String(x.id)===String(id)?obj:x):[obj,...arr];state.documents=Array.isArray(state.documents)?state.documents:[];
 attachments.forEach((a,i)=>state.documents.push({...a,id:`DOC-${permitId}-${Date.now()}-${i}`,description:`Adjunto de ${name}`,routeArea:'Documentos y Permisos',routeCollection:'permits',contextModule:'documentos-permisos',contextCollection:'permits',contextRecordId:permitId,permitId,createdAt:now(),createdBy:currentUser().name}));
 audit(old?'PERMIT_EDIT':'PERMIT_CREATE',`${obj.name} · ${obj.expiryDate||'sin vencimiento'} · ${attachments.length} adjuntos`);
 if(!save()){restoreStateSnapshot(snapshot);return}close();render();toast(attachments.length?`Documento guardado con ${attachments.length} adjunto(s)`:'Documento guardado');
}
function loansModule(){const rows=localSearch(state.loans||[],'_loansQ'),principal=rows.reduce((a,x)=>a+Number(x.principal||0),0),paid=(state.loanPayments||[]).reduce((a,x)=>a+Number(x.amount||0),0);return head('Créditos y Préstamos','Registro de obligaciones y pagos realizados. El saldo mostrado resta los pagos registrados del principal y no calcula intereses devengados.',`<button class="btn primary" data-action="loan-new">＋ Nuevo crédito</button> <button class="btn" data-action="loan-export">Excel + CSV</button> <button class="btn" data-action="loan-print">Imprimir / PDF</button>`)+`<div class="grid"><div class="card kpi"><small>Créditos activos</small><strong>${rows.filter(x=>x.status!=='CERRADO').length}</strong></div><div class="card kpi"><small>Principal registrado</small><strong>${money(principal)}</strong></div><div class="card kpi"><small>Pagos registrados</small><strong>${money(paid)}</strong></div></div><div class="card" style="margin-top:14px"><div class="toolbar"><input id="loanQ" class="input search" value="${esc(state._loansQ||'')}" placeholder="Buscar entidad o crédito"></div><div class="catalog-results">${rows.map(x=>{const p=(state.loanPayments||[]).filter(q=>String(q.loanId)===String(x.id)),balance=Math.max(0,Number(x.principal||0)-p.reduce((a,q)=>a+Number(q.amount||0),0));return `<article class="catalog-card"><div class="catalog-title"><span class="status">${esc(x.status||'ACTIVO')}</span><h3>${esc(x.name||x.lender||'Crédito')}</h3></div><div class="catalog-grid"><div><small>Entidad</small><b>${esc(x.lender||'—')}</b></div><div><small>Principal</small><b>${money(x.principal)}</b></div><div><small>Pagos registrados</small><b>${money(p.reduce((a,q)=>a+Number(q.amount||0),0))}</b></div><div><small>Saldo principal aproximado</small><b>${money(balance)}</b></div><div><small>Tasa / frecuencia</small><b>${esc(x.rate||0)}% · ${esc(x.frequency||'—')}</b></div><div><small>Próximo vencimiento</small><b>${esc(x.nextDue||'—')}</b></div></div><div class="catalog-actions"><button class="btn primary" data-action="loan-payment-new" data-id="${esc(x.id)}">Registrar pago</button> <button class="btn" data-action="loan-edit" data-id="${esc(x.id)}">Editar</button> <button class="btn" data-action="loan-history" data-id="${esc(x.id)}">Historial</button> <button class="btn danger" data-action="loan-delete" data-id="${esc(x.id)}">Eliminar</button></div></article>`}).join('')||'<div class="card empty">No hay créditos registrados.</div>'}</div></div>`}
function loanModal(id=''){const r=(state.loans||[]).find(x=>String(x.id)===String(id));modal(`<h3>${r?'Editar':'Nuevo'} crédito o préstamo</h3><div class="formgrid"><div class="field full"><label>Nombre / propósito *</label><input id="lnName" value="${esc(r?.name||'')}"></div><div class="field"><label>Prestamista</label><input id="lnLender" value="${esc(r?.lender||'')}"></div><div class="field"><label>Principal</label><input id="lnPrincipal" type="number" min="0" step=".01" value="${Number(r?.principal||0)}"></div><div class="field"><label>Tasa anual %</label><input id="lnRate" type="number" min="0" step=".01" value="${Number(r?.rate||0)}"></div><div class="field"><label>Frecuencia de pago</label><select id="lnFrequency">${['Semanal','Quincenal','Mensual','Trimestral','Anual','Otra'].map(v=>`<option ${r?.frequency===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Próximo vencimiento</label><input id="lnDue" type="date" value="${esc(r?.nextDue||'')}"></div><div class="field"><label>Estado</label><select id="lnStatus">${['ACTIVO','CERRADO','PAUSADO'].map(v=>`<option ${String(r?.status||'ACTIVO')===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field full"><label>Notas</label><textarea id="lnNotes">${esc(r?.notes||'')}</textarea></div></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="loan-save" data-id="${esc(id)}">Guardar</button></div>`)}
function saveLoan(id=''){const name=document.getElementById('lnName')?.value.trim(),principal=Number(document.getElementById('lnPrincipal')?.value||0),rate=Number(document.getElementById('lnRate')?.value||0);if(!name||!Number.isFinite(principal)||!(principal>0))return toast('Indica nombre y principal mayor que cero');if(!Number.isFinite(rate)||rate<0||rate>100)return toast('La tasa anual debe estar entre 0 y 100%.');const arr=state.loans||[],old=arr.find(x=>String(x.id)===String(id)),nextDue=document.getElementById('lnDue')?.value||'';if(id&&!old)return toast('No se encontró el crédito para editar.');if(nextDue&&(!/^\d{4}-\d{2}-\d{2}$/.test(nextDue)||!Number.isFinite(new Date(nextDue+'T12:00:00').getTime())||new Date(nextDue+'T12:00:00').toISOString().slice(0,10)!==nextDue))return toast('Indica una fecha de vencimiento válida.');const paid=(state.loanPayments||[]).filter(x=>String(x.loanId)===String(id)).reduce((sum,x)=>sum+Number(x.amount||0),0);if(old&&paid>principal+0.00001)return toast('El principal no puede quedar por debajo de los pagos ya registrados.');const obj={...(old||{}),id:old?.id||'LOAN-'+Date.now(),name,lender:document.getElementById('lnLender')?.value.trim()||'',principal,rate,frequency:document.getElementById('lnFrequency')?.value||'Mensual',nextDue,status:document.getElementById('lnStatus')?.value||'ACTIVO',notes:document.getElementById('lnNotes')?.value.trim()||'',createdAt:old?.createdAt||now(),updatedAt:now()},snapshot=JSON.stringify(state);state.loans=old?arr.map(x=>String(x.id)===String(id)?obj:x):[obj,...arr];audit(old?'LOAN_EDIT':'LOAN_CREATE',`${obj.name} · ${money(obj.principal)}`);if(!save()){restoreStateSnapshot(snapshot);return}close();render();toast('Crédito guardado')}
function loanPaymentModal(id,paymentId=''){const loan=(state.loans||[]).find(x=>String(x.id)===String(id)),old=paymentId?(state.loanPayments||[]).find(x=>String(x.id)===String(paymentId)):null;if(!loan)return toast('Crédito no encontrado');modal(`<h3>${old?'Editar pago':'Registrar pago'} · ${esc(loan.name)}</h3><div class="formgrid"><div class="field"><label>Fecha</label><input id="lpDate" type="date" value="${esc(old?.date||now().slice(0,10))}"></div><div class="field"><label>Monto pagado</label><input id="lpAmount" type="number" min="0.01" step=".01" value="${Number(old?.amount||0)||''}"></div><div class="field"><label>Referencia</label><input id="lpRef" value="${esc(old?.reference||'')}"></div><div class="field full"><label>Notas</label><textarea id="lpNotes">${esc(old?.notes||'')}</textarea></div></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="loan-payment-save" data-id="${esc(id)}" data-payment-id="${esc(paymentId)}">Guardar pago</button></div>`)}
function saveLoanPayment(id,paymentId=''){const loan=(state.loans||[]).find(x=>String(x.id)===String(id));if(!loan)return toast('Crédito no encontrado');const amount=Number(document.getElementById('lpAmount')?.value||0),date=document.getElementById('lpDate')?.value||now().slice(0,10);if(!Number.isFinite(amount)||!(amount>0))return toast('Indica un monto pagado válido');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(new Date(date+'T12:00:00').getTime())||new Date(date+'T12:00:00').toISOString().slice(0,10)!==date)return toast('Indica una fecha válida.');const arr=state.loanPayments||[],old=paymentId?arr.find(x=>String(x.id)===String(paymentId)):null;if(paymentId&&!old)return toast('No se encontró el pago.');if(old&&String(old.loanId)!==String(id))return toast('El pago no pertenece a este crédito.');const paidOthers=arr.filter(x=>String(x.loanId)===String(id)&&String(x.id)!==String(paymentId)).reduce((sum,x)=>sum+Number(x.amount||0),0);if(paidOthers+amount>Number(loan.principal||0)+0.00001)return toast('El pago supera el saldo de principal registrado.');const p={...(old||{}),id:old?.id||'PAY-'+Date.now(),loanId:id,date,amount,reference:document.getElementById('lpRef')?.value.trim()||'',notes:document.getElementById('lpNotes')?.value.trim()||'',createdAt:old?.createdAt||now(),updatedAt:now()},snapshot=JSON.stringify(state);state.loanPayments=old?arr.map(x=>String(x.id)===String(paymentId)?p:x):[p,...arr];audit(old?'LOAN_PAYMENT_EDIT':'LOAN_PAYMENT_CREATE',`${loan.name} · ${p.date} · ${money(p.amount)}`);if(!save()){restoreStateSnapshot(snapshot);return}close();render();toast(old?'Pago actualizado':'Pago registrado')}
function deleteLoanPayment(paymentId){const p=(state.loanPayments||[]).find(x=>String(x.id)===String(paymentId));if(!p)return toast('No se encontró el pago.');if(!confirm('¿Eliminar este pago registrado? El saldo del crédito aumentará.'))return;const snapshot=JSON.stringify(state);state.loanPayments=(state.loanPayments||[]).filter(x=>String(x.id)!==String(paymentId));audit('LOAN_PAYMENT_DELETE',`${p.loanId} · ${p.date} · ${money(p.amount)}`);if(!save()){restoreStateSnapshot(snapshot);return}close();render();loanHistory(p.loanId)}
function loanHistory(id){const loan=(state.loans||[]).find(x=>String(x.id)===String(id)),rows=(state.loanPayments||[]).filter(x=>String(x.loanId)===String(id)).sort((a,b)=>String(b.date).localeCompare(String(a.date)));modal(`<h3>Pagos · ${esc(loan?.name||'Crédito')}</h3>${rowsTable([['Fecha'],['Monto'],['Referencia'],['Notas']],rows.map(x=>`<tr><td>${esc(x.date||'—')}</td><td>${money(x.amount)}</td><td>${esc(x.reference||'—')}</td><td>${esc(x.notes||'—')}</td><td><button class="btn" data-action="loan-payment-edit" data-id="${esc(x.id)}" data-loan-id="${esc(id)}">Editar</button> <button class="btn danger" data-action="loan-payment-delete" data-id="${esc(x.id)}">Eliminar</button></td></tr>`).join(''),'No hay pagos registrados.')}<div class="actions"><button class="btn" data-action="close">Cerrar</button></div>`)}
